/*
 * A070886  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 90".
 * https://oeis.org/A070886
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, nice, easy
 * Formula:   Let r = ⌊√n⌋ and i = n – r². If i is odd, a(n)=0;
 * Range:     u8 n <= 9999, u16 n <= 9999, u32 n <= 9999, u64 n <= 9999,
 *            u128 n <= 9999, big any n
 * Helpers:   floor_isqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A070886 – Rule 90 cellular automaton (Sierpinski triangle)  */
/*  otherwise let k = i/2.  Then a(n) = binomial(r,k) mod 2,        */
/*  which equals 1 iff (k & r) == k (Lucas' theorem).           */
/*  E.g. a(0)=1, a(1)=1, a(2)=0, a(3)=1, a(4)=1, etc.           */

#include "../utils/floor_isqrt.h"   /* provides floor_isqrt(idx_t) */

seq_t a(idx_t n)
{
    /* Compute r = floor(sqrt(n)) */
    idx_t r = floor_isqrt(n);

    /* Offset within row r */
    idx_t offset = n - r * r;       /* n - r^2 */

    /* If offset is odd → 0 */
    if (offset & 1u)
        return 0;

    /* k = offset / 2 */
    idx_t k = offset >> 1;

    /* Binomial(r,k) mod 2 is 1 iff all bits of k are set in r */
    return ((k & r) == k) ? (seq_t)1 : (seq_t)0;
}
